def add_shona_content(apps, schema_editor):
    Topic = apps.get_model("education", "Topic")
    Article = apps.get_model("education", "Article")
    ArticleTranslation = apps.get_model("education", "ArticleTranslation")
    Language = apps.get_model("core", "Language")

    shona = Language.objects.get(code="sn")
    for slug, (name, description) in TOPICS.items():
        Topic.objects.filter(slug=slug).update(shona_name=name, shona_description=description)

    for slug, (title, summary, content) in SHONA_ARTICLES.items():
        article = Article.objects.get(slug=slug)
        translation, _ = ArticleTranslation.objects.get_or_create(
            article=article,
            language=shona,
            defaults={
                "title": title,
                "summary": summary,
                "content": content,
                "review_status": "draft",
                "reviewed_at": None,
            },
        )
        translation.title = title
        translation.summary = summary
        translation.content = content
        translation.review_status = "draft"
        translation.reviewed_at = None
        translation.save()


def remove_shona_content(apps, schema_editor):
    Topic = apps.get_model("education", "Topic")
    Article = apps.get_model("education", "Article")
    ArticleTranslation = apps.get_model("education", "ArticleTranslation")
    Language = apps.get_model("core", "Language")

    shona = Language.objects.get(code="sn")
    for slug in TOPICS:
        Topic.objects.filter(slug=slug).update(shona_name="", shona_description="")

    for slug, (title, summary, content) in ORIGINAL_SHONA.items():
        article = Article.objects.get(slug=slug)
        ArticleTranslation.objects.update_or_create(
            article=article,
            language=shona,
            defaults={
                "title": title,
                "summary": summary,
                "content": content,
                "review_status": "draft",
                "reviewed_at": None,
            },
        )

    new_article_slugs = set(SHONA_ARTICLES) - set(ORIGINAL_SHONA)
    ArticleTranslation.objects.filter(
        article__slug__in=new_article_slugs,
        language=shona,
    ).delete()


